#if UNITY_EDITOR
using LastRail.Battle;
using NUnit.Framework;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using System;
using System.IO;
using System.Threading.Tasks;
namespace LastRail.Tests.EditMode {
 public sealed class EquipmentSafeTransitionTests {
  [Test] public void StrictDiagnosticConsumerMustExist(){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType("LastRail.Run.EquipmentSafeTransitionContext"));}
  static JObject Sample()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/equipment-safe-transition-tcp-20261005.json"));
  static string Hash(JToken p)=>BDirectAttackInput.Digest(p).Substring(7);
  static JObject Repin(JObject p,string key){p.Remove(key);p[key]=Hash(p);return p;}
  static EquipmentSafeTransitionContext Context(JObject p=null){p=p??(JObject)Sample()["context"];return EquipmentSafeTransitionContext.Read(p.ToString(),(string)p["contextHash"],"a",(string)p["lineage"]["runId"]);}
  static EquipmentSafeTransitionReceipt Receipt(EquipmentSafeTransitionIntent i,JObject p=null){p=p??(JObject)Sample()["packet"];return EquipmentSafeTransitionReceipt.Read(p.ToString(),(string)p["transitionHash"],i);}
  [Test] public void OriginalTcpSampleCreatesExactIntentAndRestoresDiagnosticWithoutGrant(){var c=Context();var i=c.CreateIntent("VERIFY_LOCAL","ENTER","BETWEEN_NODES");Assert.IsTrue(JToken.DeepEquals(i.Capture(),Sample()["requestFromContext"]));var r=Receipt(i);Assert.IsFalse(c.CanAuthorizeMaintenance);Assert.IsFalse(r.CanAuthorizeMaintenance);Assert.IsTrue(JToken.DeepEquals(r.Capture(),Receipt(i,r.Capture()).Capture()));r.Capture()["accepted"]=true;Assert.IsFalse((bool)r.Capture()["accepted"]);i.Capture()["expectedMapRevision"]=999;Assert.AreEqual(4,(long)i.Capture()["expectedMapRevision"]);}
  [Test] public void MissingMapReceiptCannotBeInvented(){var p=(JObject)Sample()["context"];p["mapEventId"]=JValue.CreateNull();var c=Context(Repin(p,"contextHash"));Assert.Throws<InvalidOperationException>(()=>c.CreateIntent("next","ENTER","BETWEEN_NODES"));Assert.IsFalse(c.CanAuthorizeMaintenance);}
  [TestCase("accepted")][TestCase("runtimeSupported")][TestCase("journalChanged")][TestCase("clockChanged")]
  public void ClientCannotPromoteDiagnosticBooleans(string key){var p=(JObject)Sample()["packet"];p[key]=true;Repin(p,"transitionHash");Assert.Throws<ArgumentException>(()=>Receipt(Context().CreateIntent("VERIFY_LOCAL","ENTER","BETWEEN_NODES"),p));}
  [Test] public void ExactSourcePinsIdentityRequestHoldOrderAndAuthorityRequired(){var c=Context();var i=c.CreateIntent("VERIFY_LOCAL","ENTER","BETWEEN_NODES");foreach(var key in new[]{"requestHash","commandId","kind"}){var p=(JObject)Sample()["packet"];p[key]="wrong";Repin(p,"transitionHash");Assert.Throws<ArgumentException>(()=>Receipt(i,p));}foreach(var key in new[]{"runId","accountId","snapshotHash","mapRevision","holdIds"}){var p=(JObject)Sample()["packet"];p["lineage"][key]=key=="mapRevision"?new JValue(5):key=="holdIds"?(JToken)new JArray("other"):new JValue("wrong");Repin(p,"transitionHash");Assert.Throws<ArgumentException>(()=>Receipt(i,p));}Assert.Throws<ArgumentException>(()=>EquipmentSafeTransitionContext.Read(c.Capture().ToString(),c.Hash,"b",c.RunId));Assert.Throws<ArgumentException>(()=>EquipmentSafeTransitionContext.Read(c.Capture().ToString(),new string('0',64),"a",c.RunId));}
  [Test] public void StrictShapeRejectsUnknownDuplicateCommentTrailingAndNonintegerRevision(){var c=Context();var p=c.Capture();p["paused"]=true;Repin(p,"contextHash");Assert.Throws<ArgumentException>(()=>Context(p));Assert.Throws<Newtonsoft.Json.JsonReaderException>(()=>EquipmentSafeTransitionContext.Read(c.Capture().ToString().Replace("\"accepted\": false","\"accepted\": false,\"accepted\": false"),c.Hash,"a",c.RunId));Assert.Throws<ArgumentException>(()=>EquipmentSafeTransitionContext.Read("/*hidden*/"+c.Capture(),c.Hash,"a",c.RunId));Assert.Throws<Newtonsoft.Json.JsonReaderException>(()=>EquipmentSafeTransitionContext.Read(c.Capture()+" {}",c.Hash,"a",c.RunId));p=c.Capture();p["lineage"]["mapRevision"]=4.5;Repin(p,"contextHash");Assert.Throws<ArgumentException>(()=>Context(p));}
  [Test] public async Task PublicationGenerationRejectsRebindUnbindDisposeAndOutOfOrder(){var c=Context();var i=c.CreateIntent("VERIFY_LOCAL","ENTER","BETWEEN_NODES");var r=Receipt(i);using(var o=new EquipmentSafeTransitionOwner()){int calls=0;o.Bind("a",c.RunId,_=>calls++);var pending=new TaskCompletionSource<EquipmentSafeTransitionReceipt>();var late=o.PublishAsync(i,()=>pending.Task);Assert.IsTrue(await o.PublishAsync(i,()=>Task.FromResult(r)));pending.SetResult(r);Assert.IsFalse(await late);Assert.AreEqual(1,calls);pending=new TaskCompletionSource<EquipmentSafeTransitionReceipt>();late=o.PublishAsync(i,()=>pending.Task);o.Bind("b","another-run",_=>calls++);pending.SetResult(r);Assert.IsFalse(await late);Assert.Throws<ArgumentException>(()=>o.PublishAsync(i,()=>Task.FromResult(r)).GetAwaiter().GetResult());o.Bind("a",c.RunId,_=>calls++);pending=new TaskCompletionSource<EquipmentSafeTransitionReceipt>();late=o.PublishAsync(i,()=>pending.Task);o.Unbind();pending.SetResult(r);Assert.IsFalse(await late);o.Bind("a",c.RunId,_=>calls++);pending=new TaskCompletionSource<EquipmentSafeTransitionReceipt>();late=o.PublishAsync(i,()=>pending.Task);o.Dispose();pending.SetResult(r);Assert.IsFalse(await late);Assert.AreEqual(1,calls);}}
 }
}
#endif
